    earliest_day = float('inf')

    # Iterate over each day to check if it is a not so rainy day
    for d in range(1, n + 1):
        # Check the x days before the current day
        if d - x > 0:
            for j in range(d - x, d):
                if rain_amounts[d - 1] >= rain_amounts[j - 1]:
                    break
            else:
                # Check the y days after the current day
                for j in range(d, min(d + y, n) + 1):
                    if rain_amounts[d - 1] >= rain_amounts[j - 1]:
                        break
                else:
                    # If it is not so rainy, update the earliest day
                    earliest_day = min(earliest_day, d)

    # Return the earliest not so rainy day
    return earliest_day

